.vw-mobile .seo-footer__grid { grid-template-columns: 1fr; }
.vw-mobile .seo-meta__row { flex-direction: column; gap: 0; }

/* ============================================================
   wave 11 · Calm Harbor — CMS media slot with a real image
   (seo-media) + retail product teaser (seo-products-teaser)
   ============================================================ */
.seo-media[data-state="ready"] { border-style: solid; border-color: rgba(var(--hair),.14); background: none; min-height: 0; padding: 0; }
.seo-media__img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; display: block; }
.seo-hero__media.seo-media[data-state="ready"] { aspect-ratio: 4 / 3; border-color: rgba(255,255,255,.28); }
.seo-proof__media { margin-bottom: 24px; }
.seo-proof__media[data-state="ready"] { aspect-ratio: 21 / 9; }

.seo-teaser__grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 16px; }
.seo-teaser-card { cursor: pointer; transition: transform .16s ease, box-shadow .16s ease; }
.seo-teaser-card:hover { transform: translateY(-2px); box-shadow: 0 14px 34px rgba(13,38,76,.12); }
.seo-teaser-card:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.seo-teaser-card .product-card__art { position: relative; overflow: hidden; }
.seo-teaser-card__img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
.seo-teaser-card__go { font-size: 13px; font-weight: 700; color: var(--accent); white-space: nowrap; }
.seo-teaser-card[data-state="loading"] { min-height: 230px; gap: 10px; justify-content: center; }
.seo-teaser__cta { display: flex; align-items: center; gap: 14px; flex-wrap: wrap; margin-top: 24px; }
.seo-teaser__note { font-size: 12px; color: var(--ink-3); }
.seo-teaser__empty { border: 1px dashed rgba(var(--hair),.25); border-radius: var(--radius-card); padding: 26px 24px; font-size: 13px; line-height: 1.5; color: var(--ink-2); max-width: 560px; }
.seo-teaser__empty-title { font-weight: 700; font-size: 14px; color: var(--ink); margin-bottom: 4px; }

/* wave 11 responsive (same container-width mechanism as the rest) */
.vw-tablet .seo-teaser__grid { grid-template-columns: repeat(2, 1fr); }
.vw-mobile .seo-teaser__grid { grid-template-columns: repeat(2, 1fr); gap: 10px; }
.vw-tablet .seo-hero__media.seo-media[data-state="ready"] { aspect-ratio: 16 / 9; }
.vw-mobile .seo-hero__media.seo-media[data-state="ready"] { aspect-ratio: 3 / 2; }
.vw-tablet .seo-proof__media[data-state="ready"] { aspect-ratio: 16 / 9; }
.vw-mobile .seo-proof__media[data-state="ready"] { aspect-ratio: 4 / 3; }

/* wave 12 · pim.pricing[] rows — optional shortDescription line */
.seo-price__desc { display: block; font-size: 12px; font-weight: 400; color: var(--ink-3); margin-top: 2px; }
.seo-price__val { white-space: nowrap; } /* wave 12 — keep "displayPrice / interval" on one line */

